import { Injectable, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Router } from '@angular/router';
import { environment } from '../../environment/environment';

export interface AuthUser {
  id: string;
  name: string;
  email: string;
}

interface AuthResponse {
  token: string;
  user: AuthUser;
}

@Injectable({ providedIn: 'root' })
export class AuthService {
  private tokenKey = 'eos_token';
  private userKey = 'eos_user';

  currentUser = signal<AuthUser | null>(this.readUser());

  constructor(private http: HttpClient, private router: Router) {}

  signup(name: string, email: string, password: string) {
    return this.http.post<AuthResponse>(`${environment.apiUrl}/auth/signup`, { name, email, password })
      .subscribe({ next: (res) => this.storeSession(res) });
  }

  sendOtp(name: string, email: string, phone: string, password: string, onError?: (msg: string) => void) {
    this.http.post(`${environment.apiUrl}/auth/send-otp`, { name, email, phone, password })
      .subscribe({
        next: () => {},
        error: (err) => onError?.(err?.error?.error || 'Could not send verification code'),
      });
  }

  verifyOtp(phone: string, code: string, onSuccess: () => void, onError?: (msg: string) => void) {
    this.http.post(`${environment.apiUrl}/auth/verify-otp`, { phone, code })
      .subscribe({
        next: () => onSuccess(),
        error: (err) => onError?.(err?.error?.error || 'Incorrect code'),
      });
  }

  login(email: string, password: string, onError?: (msg: string) => void) {
    this.http.post<AuthResponse>(`${environment.apiUrl}/auth/login`, { email, password })
      .subscribe({
        next: (res) => this.storeSession(res),
        error: (err) => onError?.(err?.error?.error || 'Login failed'),
      });
  }

  logout() {
    localStorage.removeItem(this.tokenKey);
    localStorage.removeItem(this.userKey);
    this.currentUser.set(null);
    this.router.navigate(['/login']);
  }

  getToken(): string | null {
    return localStorage.getItem(this.tokenKey);
  }

  isLoggedIn(): boolean {
    return !!this.getToken();
  }

  private storeSession(res: AuthResponse) {
    localStorage.setItem(this.tokenKey, res.token);
    localStorage.setItem(this.userKey, JSON.stringify(res.user));
    this.currentUser.set(res.user);
    this.router.navigate(['/app']);
  }

  private readUser(): AuthUser | null {
    const raw = localStorage.getItem(this.userKey);
    return raw ? JSON.parse(raw) : null;
  }
}
